class DLMRefreshPolicy:
    """Adaptive feature cache with dynamic interval adjustment."""

    policy_name = "adaptive_feature_v2"

    # Per-workload base intervals (prompt_interval, gen_interval, transfer_ratio)
    _BASE_PRESETS = {
        "math": (7, 50, 0.25),
        "humaneval": (8, 50, 0.25),
        "lm_eval": (3, 50, 0.25),
    }

    def block_schedule(self, request_meta):
        wl = WORKLOAD_CONFIGS[request_meta["workload"]]
        return {
            "gen_length": wl["gen_length"],
            "block_length": wl["block_length"],
            "num_steps": wl["num_steps"],
            "warmup_forward": False,
        }

    def query_plan(self, step_meta, mask_state, cache_state):
        return {
            "query_scope": "full_sequence",
            "query_positions": None,
            "track_positions": [],
            "masked_window": None,
        }

    def cache_refresh_plan(self, layer_meta, step_meta, token_stats, cache_state):
        workload = step_meta["workload"]
        base_prompt, base_gen, base_transfer = self._BASE_PRESETS.get(
            workload, (4, 50, 0.25)
        )

        if token_stats:
            avg_difficulty = sum(t["difficulty"] for t in token_stats) / len(token_stats)
            avg_similarity = sum(t["similarity"] for t in token_stats) / len(token_stats)
            avg_importance = sum(t["importance"] for t in token_stats) / len(token_stats)
        else:
            avg_difficulty = 0.5
            avg_similarity = 1.0
            avg_importance = 0.5

        # Adjust gen_interval: higher difficulty -> refresh more often (smaller interval)
        # Use factor range 0.5 to 2.0
        difficulty_factor = 1.0 + avg_difficulty  # 1.0 to 2.0
        gen_interval = max(1, int(base_gen / difficulty_factor))

        # Adjust transfer_ratio: lower similarity -> transfer more rows
        similarity_factor = max(0.1, avg_similarity)
        transfer_ratio = base_transfer * (1.0 / similarity_factor)
        transfer_ratio = min(0.5, transfer_ratio)

        # Optional: adjust prompt_interval based on importance (high importance -> refresh less)
        importance_factor = 1.0 + avg_importance  # 1.0 to 2.0
        prompt_interval = max(1, int(base_prompt * importance_factor))

        return {
            "use_feature_cache": True,
            "prompt_refresh_interval": prompt_interval,
            "gen_refresh_interval": gen_interval,
            "transfer_ratio": transfer_ratio,
            "row_selector": "lowest_value_feature_similarity",
            "kv_update": "scatter_refresh",
            "layer_reset": None,
        }

    def attention_probe_plan(self, layer_meta, step_meta):
        return {
            "need_attention_weights": False,
            "rollout_p": 0.0,
            "current_k": 0,
            "gamma": None,
            "track_num": 0,
        }

    def token_transfer_plan(self, logits, mask_state, step_meta):
        return {
            "mode": "low_confidence",
            "scope": "current_block",
            "num_transfer_tokens": step_meta["default_num_transfer_tokens"],
            "threshold": None,
            "force_one": True,
        }

    def after_step(self, step_meta, logits, attention_stats, transfer_state, cache_state):
        # Store statistics for potential future use
        cache_state.setdefault("token_stats_history", []).append({
            "step": step_meta["step"],
            "avg_difficulty": sum(t["difficulty"] for t in token_stats) / len(token_stats) if token_stats else 0.5,
        })
        return cache_state

def after_step(self, step_meta, logits, attention_stats, transfer_state, cache_state):
        # No per-step adaptation needed
        return cache_state

